// BAGDROP -- inline (base64) copies of public/logo-full-white.png and
// public/signature-stamp.png, used by QuotePDF.tsx.
//
// Why inline instead of <Image src="/logo-full-white.png">: react-pdf's
// Node-side image loader treats a root-relative path as a filesystem path,
// not a URL -- it resolves fine when QuotePDF renders in the browser (the
// "Download PDF" button on the Booking Workflow page), but throws/silently
// drops the image when the exact same component is rendered server-side
// (lib/quote-pdf.ts's buildQuotePdfBuffer -- used for the WhatsApp-attached
// and emailed quote PDF). That is why a WhatsApp-sent quote was missing the
// Bagdrop logo (and the signature stamp) even though a manually-downloaded
// copy of the same quote looked correct (2026-09-02 fix). Same root cause
// and same fix already applied once for the invoice logo -- see
// lib/invoice-logo.ts's LOGO_ICON_DATA_URI comment for the full
// explanation. A data URI has no path to resolve, so it works identically
// in the browser and server-side.
export const LOGO_FULL_WHITE_DATA_URI =
  'data:image/png;base64,'

export const SIGNATURE_STAMP_DATA_URI =
  'data:image/png;base64,'
